//! Platform + remote URL parsing (GitHub / GitLab / Gitea / self-hosted).
//! (Generated by v0.6.0 Step 3 Phase 1)

use crate::platform::error::PlatformError;

/// Which platform a remote URL targets.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PlatformKind {
    /// `github.com`.
    GitHub,
    /// `gitlab.com`.
    GitLab,
    /// `gitea.com`.
    Gitea,
    /// A self-hosted instance (host not in the known SaaS list).
    SelfHosted,
}

/// The SaaS hosts and the platform each one owns.
const SAAS_HOSTS: [(&str, PlatformKind); 3] = [
    ("github.com", PlatformKind::GitHub),
    ("gitlab.com", PlatformKind::GitLab),
    ("gitea.com", PlatformKind::Gitea),
];

impl PlatformKind {
    /// Classify a bare host into a platform kind.
    ///
    /// `github.com`, `gitlab.com`, `gitea.com` map to their owned variants;
    /// any other host (e.g. `git.example.com`) is
    /// [`PlatformKind::SelfHosted`]. The host must be port-free (see
    /// [`parse_remote`]) and is compared case-insensitively
    /// (DNS is), so a `GitHub.com` remote is not misread as self-hosted — which
    /// would tell the user their platform is unsupported.
    pub fn from_host(host: &str) -> Self {
        SAAS_HOSTS
            .iter()
            .find(|(known, _)| host.eq_ignore_ascii_case(known))
            .map_or(PlatformKind::SelfHosted, |(_, kind)| *kind)
    }

    /// Human-readable platform label (used in errors / UI).
    pub const fn as_str(&self) -> &'static str {
        match self {
            PlatformKind::GitHub => "GitHub",
            PlatformKind::GitLab => "GitLab",
            PlatformKind::Gitea => "Gitea",
            PlatformKind::SelfHosted => "SelfHosted",
        }
    }

    /// The environment variable that carries this platform's token — the single
    /// source for every user-facing hint.
    ///
    /// `""` when the platform registers no env var (self-hosted): callers must
    /// fall back to neutral wording rather than name a variable that does not
    /// exist. Returning an empty string keeps the absence explicit instead of
    /// parking a copy-only value here that no reader would ever consume.
    pub const fn token_var(self) -> &'static str {
        match self {
            PlatformKind::GitHub => "GITHUB_TOKEN",
            PlatformKind::GitLab => "GITLAB_TOKEN",
            PlatformKind::Gitea => "GITEA_TOKEN",
            PlatformKind::SelfHosted => "",
        }
    }

    /// The CLI whose `auth token` subcommand resolves this platform's token;
    /// `""` when the platform has no standard token CLI (Gitea, self-hosted).
    pub const fn cli_hint(self) -> &'static str {
        match self {
            PlatformKind::GitHub => "gh",
            PlatformKind::GitLab => "glab",
            PlatformKind::Gitea | PlatformKind::SelfHosted => "",
        }
    }

    /// Name of the fourth receipt tab, for the panel title, the footer key hint
    /// and the command palette row alike.
    ///
    /// GitLab serves this list as To-Dos, so naming the slot `通知` under a
    /// `To-Dos` title would be two names for one thing on one screen. It lives
    /// here, beside the other platform copy, because it is platform vocabulary
    /// rather than a rendering decision — a per-panel copy is exactly what let
    /// the footer and the title drift apart.
    pub const fn notifications_label(self) -> &'static str {
        match self {
            PlatformKind::GitLab => "To-Dos",
            PlatformKind::GitHub | PlatformKind::Gitea | PlatformKind::SelfHosted => "通知",
        }
    }
}

/// [`PlatformKind::notifications_label`] for a repository whose remote has not
/// been parsed yet, so the receipt tab keeps its neutral name.
pub const fn notifications_label(kind: Option<PlatformKind>) -> &'static str {
    match kind {
        Some(platform) => platform.notifications_label(),
        None => PlatformKind::GitHub.notifications_label(),
    }
}

/// A parsed git remote URL with its target platform.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlatformRemote {
    /// Platform family (GitHub / GitLab / Gitea / SelfHosted).
    pub kind: PlatformKind,
    /// REST origin scheme: `https`, or `http` when the remote itself is HTTP.
    pub scheme: String,
    /// Bare host without scheme, userinfo, or port (e.g. `github.com`).
    pub host: String,
    /// Explicit port from the remote URL; `None` when it uses the default.
    pub port: Option<u16>,
    /// Full namespace path, e.g. `group/subgroup/project` on GitLab.
    pub path: String,
    /// Namespace above the repository: `owner` for two-segment paths,
    /// `group/subgroup` for GitLab subgroups.
    pub owner: String,
    /// Repository (last path segment): `repo`.
    pub repo: String,
}

impl PlatformRemote {
    /// REST origin: `{scheme}://{host}[:{port}]`.
    pub fn origin(&self) -> String {
        match self.port {
            Some(port) => format!("{}://{}:{}", self.scheme, self.host, port),
            None => format!("{}://{}", self.scheme, self.host),
        }
    }

    /// REST API base URL: `{origin}/api/{version}` — Gitea uses `v1`, GitLab `v4`.
    pub fn api_base(&self, version: &str) -> String {
        format!("{}/api/{}", self.origin(), version)
    }
}

/// Parse a git remote URL into a [`PlatformRemote`].
///
/// Supports `https://`, `http://`, `ssh://`, `git://`, and the scp-like
/// `[user@]host:owner/repo` forms for github.com, gitlab.com, gitea.com, and
/// arbitrary self-hosted hosts. The scheme and port are preserved (the REST
/// origin is rebuilt via [`PlatformRemote::api_base`]); only `ssh://`, `git://`
/// and the scp-like form fall back to `https`, since those protocols cannot
/// carry REST traffic.
pub fn parse_remote(url: &str) -> Result<PlatformRemote, PlatformError> {
    let trimmed = url.trim();
    let (scheme, host_port, path) = strip_scheme(trimmed)
        .ok_or_else(|| PlatformError::NotPlatform(format!("远端地址格式不正确：{url}")))?;
    let (host, port) = split_host_port(host_port);
    let path = path.trim_matches('/');
    // A trailing slash hides the `.git` suffix from a `trim_end_matches` on the
    // whole URL (`…/repo.git/`), so it is stripped from the last path segment.
    let path = path.strip_suffix(".git").unwrap_or(path);
    // The kind decides how `path` is cut, so it must be known before the split.
    let kind = PlatformKind::from_host(host);
    let (owner, repo) = split_namespace(path, kind)?;
    Ok(PlatformRemote {
        kind,
        scheme: scheme.to_string(),
        host: host.to_string(),
        port,
        path: path.to_string(),
        owner,
        repo,
    })
}

/// Strip a known scheme prefix, returning `(scheme, host[:port], path)`.
///
/// Handles `ssh://`, `git://`, `https://`, `http://` (with optional `user@`)
/// and the scp-like `[user@]host:path` form. The three non-HTTP forms report
/// `https` because the REST API is reached over HTTP(S), never over SSH/git.
fn strip_scheme(s: &str) -> Option<(&'static str, &str, &str)> {
    if let Some((host, path)) = split_scp_like(s) {
        return Some(("https", host, path));
    }
    let (scheme, rest) = if let Some(rest) = s.strip_prefix("https://") {
        ("https", strip_user(rest))
    } else if let Some(rest) = s.strip_prefix("http://") {
        ("http", strip_user(rest))
    } else if let Some(rest) = s.strip_prefix("ssh://") {
        ("https", strip_user(rest))
    } else {
        // Only the last fallback may fail; the earlier arms have already
        // handled every scheme that parses.
        let rest = s.strip_prefix("git://")?;
        ("https", strip_user(rest))
    };
    rest.split_once('/').map(|(h, p)| (scheme, h, p))
}

/// Split the scp-like `[user@]host:path` form, or `None` when `s` is not one.
///
/// Any username is accepted (`git@`, `jane@`, …) because the clone remote is
/// not always the platform's canonical one. A URL carrying userinfo
/// (`https://user@host/…`) keeps its `/` in the user segment and is therefore
/// rejected here, so it still reaches the scheme arms.
fn split_scp_like(s: &str) -> Option<(&str, &str)> {
    let (user, rest) = s.split_once('@')?;
    if user.is_empty() || user.contains('/') {
        return None;
    }
    let (host, path) = rest.split_once(':')?;
    if host.is_empty() || host.contains('/') {
        return None;
    }
    Some((host, path))
}

/// Drop the `user@` userinfo prefix from a `host[/path…]`-style remainder.
fn strip_user(s: &str) -> &str {
    match s.find('@') {
        Some(at) => &s[at + 1..],
        None => s,
    }
}

/// Split `host[:port]` into `(bare host, port)`.
///
/// The bare host drives platform classification and env-var naming; the port is
/// kept for building the REST origin. Bracketed IPv6 literals (`[::1]:8080`)
/// keep their brackets in the host. A non-numeric port is treated as part of
/// neither (host only), so the URL is still classified instead of rejected.
fn split_host_port(host: &str) -> (&str, Option<u16>) {
    if let Some(end) = host.find(']') {
        // [bracketed]:port
        let (h, rest) = host.split_at(end + 1);
        return (h, rest.strip_prefix(':').and_then(|p| p.parse().ok()));
    }
    match host.split_once(':') {
        Some((h, port)) => (h, port.parse().ok()),
        None => (host, None),
    }
}

/// Split a full namespace path into `(namespace, repository)`.
///
/// The two families read the path differently, so the split is platform-aware —
/// this is the core lesson behind this function:
///
/// - **GitHub / Gitea**: `owner/repo` is always exactly two segments. Anything
///   after `repo` is noise from a copy-pasted URL (`/issues/42`, `/tree/main`,
///   `.git`), so the first two segments win — exactly v0.5.0's
///   `split_owner_repo` (`splitn(2, '/')`, then the repo is the remainder's
///   first segment). Taking the *last* segment instead makes a valid remote
///   404 (`owner/repo/issues` + `42`) and leaks the junk into the panel title.
/// - **GitLab**: the project path is `group[/subgroup…]/project`, so the API
///   needs the whole path while the UI shows only the repository. The repo is
///   therefore the last segment and the namespace is everything before it.
/// - **SelfHosted**: no known family, so the GitLab rule applies — on a
///   two-segment path both rules agree, and on a deeper path only
///   "everything but the last" keeps a multi-level namespace intact instead of
///   silently truncating it. [`crate::platform::build_client`] rejects this
///   kind today, so the rule only needs to stay deterministic.
fn split_namespace(path: &str, kind: PlatformKind) -> Result<(String, String), PlatformError> {
    match kind {
        PlatformKind::GitHub | PlatformKind::Gitea => {
            // v0.5.0 semantics: `owner/repo[/noise…]` — first two segments.
            let path = path.trim_start_matches('/');
            let mut parts = path.splitn(2, '/');
            let owner = parts.next().filter(|s| !s.is_empty());
            let repo = parts
                .next()
                .and_then(|r| r.split('/').next())
                .filter(|s| !s.is_empty());
            match (owner, repo) {
                (Some(owner), Some(repo)) => Ok((owner.to_string(), repo.to_string())),
                _ => Err(namespace_error(path)),
            }
        }
        // GitLab (and self-hosted): the repo is the last segment, the namespace
        // is everything above it.
        _ => {
            let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
            match (segments.first(), segments.last(), segments.len()) {
                (Some(_), Some(repo), len) if len >= 2 => {
                    let owner = segments[..len - 1].join("/");
                    Ok((owner, repo.to_string()))
                }
                _ => Err(namespace_error(path)),
            }
        }
    }
}

/// The one user-facing wording for an unresolvable remote path — identical to
/// v0.5.0's `NotGitHub` message, so a failing remote never reads as a new bug.
fn namespace_error(path: &str) -> PlatformError {
    PlatformError::NotPlatform(format!("无法从远端路径解析 owner/repo：{path}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn from_host_classifies_saas() {
        assert_eq!(PlatformKind::from_host("github.com"), PlatformKind::GitHub);
        assert_eq!(PlatformKind::from_host("gitlab.com"), PlatformKind::GitLab);
        assert_eq!(PlatformKind::from_host("gitea.com"), PlatformKind::Gitea);
    }

    #[test]
    fn from_host_self_hosted() {
        assert_eq!(
            PlatformKind::from_host("git.example.com"),
            PlatformKind::SelfHosted
        );
    }

    #[test]
    fn from_host_ignores_host_case() {
        // DNS is case-insensitive, so a mixed-case remote must not be reported
        // as an unsupported self-hosted platform.
        assert_eq!(PlatformKind::from_host("GitHub.com"), PlatformKind::GitHub);
        assert_eq!(PlatformKind::from_host("GitLab.COM"), PlatformKind::GitLab);
        assert_eq!(PlatformKind::from_host("GITEA.com"), PlatformKind::Gitea);
        // Case-insensitivity must not widen the SaaS list.
        assert_eq!(
            PlatformKind::from_host("Git.Example.COM"),
            PlatformKind::SelfHosted
        );
    }

    #[test]
    fn token_var_per_platform() {
        assert_eq!(PlatformKind::GitHub.token_var(), "GITHUB_TOKEN");
        assert_eq!(PlatformKind::GitLab.token_var(), "GITLAB_TOKEN");
        assert_eq!(PlatformKind::Gitea.token_var(), "GITEA_TOKEN");
        // Self-hosted registers no env var, so the absence is explicit and
        // callers fall back to neutral wording.
        assert_eq!(PlatformKind::SelfHosted.token_var(), "");
    }

    #[test]
    fn cli_hint_per_platform() {
        assert_eq!(PlatformKind::GitHub.cli_hint(), "gh");
        assert_eq!(PlatformKind::GitLab.cli_hint(), "glab");
        // No standard token CLI for Gitea or self-hosted.
        assert_eq!(PlatformKind::Gitea.cli_hint(), "");
        assert_eq!(PlatformKind::SelfHosted.cli_hint(), "");
    }

    #[test]
    fn credential_hints_are_const_usable() {
        // `const` usable: callers bind their hints to a `const` per platform.
        const TOKEN_VAR: &str = PlatformKind::GitLab.token_var();
        const CLI_HINT: &str = PlatformKind::GitLab.cli_hint();
        assert_eq!(TOKEN_VAR, "GITLAB_TOKEN");
        assert_eq!(CLI_HINT, "glab");
    }

    #[test]
    fn as_str_labels() {
        assert_eq!(PlatformKind::GitHub.as_str(), "GitHub");
        assert_eq!(PlatformKind::GitLab.as_str(), "GitLab");
        assert_eq!(PlatformKind::Gitea.as_str(), "Gitea");
        assert_eq!(PlatformKind::SelfHosted.as_str(), "SelfHosted");
        // `const` usable: adapters bind their label to a `const`.
        const GITEA: &str = PlatformKind::Gitea.as_str();
        assert_eq!(GITEA, "Gitea");
    }

    #[test]
    fn parses_github_https() {
        let r = parse_remote("https://github.com/owner/repo.git").unwrap();
        assert_eq!(r.kind, PlatformKind::GitHub);
        assert_eq!(r.host, "github.com");
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        assert_eq!(r.path, "owner/repo");
        assert_eq!(r.port, None);
        assert_eq!(r.scheme, "https");
        assert_eq!(r.api_base("v3"), "https://github.com/api/v3");
    }

    #[test]
    fn parses_github_scp() {
        let r = parse_remote("git@github.com:owner/repo").unwrap();
        assert_eq!(r.kind, PlatformKind::GitHub);
        assert_eq!(r.host, "github.com");
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        assert_eq!(r.path, "owner/repo");
        // ssh remotes still talk to the HTTPS REST API.
        assert_eq!(r.scheme, "https");
        assert_eq!(r.api_base("v3"), "https://github.com/api/v3");
    }

    #[test]
    fn parses_scp_with_a_non_git_user_and_mixed_case_host() {
        // The clone remote is not always the platform's canonical one, and a
        // mixed-case host must still classify as its platform.
        let r = parse_remote("Git@GitHub.com:o/r").unwrap();
        assert_eq!(r.kind, PlatformKind::GitHub);
        assert_eq!(r.host, "GitHub.com");
        assert_eq!(r.owner, "o");
        assert_eq!(r.repo, "r");
        assert_eq!(r.path, "o/r");
        assert_eq!(r.scheme, "https");

        let r = parse_remote("user@gitlab.com:g/p").unwrap();
        assert_eq!(r.kind, PlatformKind::GitLab);
        assert_eq!(r.host, "gitlab.com");
        assert_eq!(r.owner, "g");
        assert_eq!(r.repo, "p");
        assert_eq!(r.path, "g/p");
    }

    #[test]
    fn strip_git_suffix_survives_a_trailing_slash() {
        // `…/repo.git/` hides the suffix from a `trim_end_matches` on the raw
        // URL; the last path segment must still be normalized.
        let r = parse_remote("https://github.com/o/r.git/").unwrap();
        assert_eq!(r.kind, PlatformKind::GitHub);
        assert_eq!(r.repo, "r");
        assert_eq!(r.owner, "o");
        assert_eq!(r.path, "o/r");

        let r = parse_remote("git@github.com:o/r.git/").unwrap();
        assert_eq!(r.repo, "r");
        assert_eq!(r.path, "o/r");

        // Without a `.git` suffix the trailing slash is still harmless.
        let r = parse_remote("https://gitea.com/owner/repo/").unwrap();
        assert_eq!(r.repo, "repo");
        assert_eq!(r.path, "owner/repo");
    }

    #[test]
    fn parses_gitea_two_segments() {
        let r = parse_remote("https://gitea.com/owner/repo").unwrap();
        assert_eq!(r.kind, PlatformKind::Gitea);
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        assert_eq!(r.path, "owner/repo");
        assert_eq!(r.api_base("v1"), "https://gitea.com/api/v1");
    }

    #[test]
    fn parses_gitlab_with_group_subgroup() {
        let r = parse_remote("https://gitlab.com/group/sub/repo").unwrap();
        assert_eq!(r.kind, PlatformKind::GitLab);
        assert_eq!(r.host, "gitlab.com");
        // The whole path is the project id; `repo` stays the last segment.
        assert_eq!(r.path, "group/sub/repo");
        assert_eq!(r.owner, "group/sub");
        assert_eq!(r.repo, "repo");
    }

    #[test]
    fn parses_gitlab_with_three_level_subgroup() {
        let r = parse_remote("https://gitlab.com/a/b/c/repo").unwrap();
        assert_eq!(r.path, "a/b/c/repo");
        assert_eq!(r.owner, "a/b/c");
        assert_eq!(r.repo, "repo");
    }

    #[test]
    fn parses_gitlab_with_single_group() {
        let r = parse_remote("https://gitlab.com/group/repo").unwrap();
        assert_eq!(r.path, "group/repo");
        assert_eq!(r.owner, "group");
        assert_eq!(r.repo, "repo");
    }

    #[test]
    fn parses_ssh_and_git_schemes() {
        let r = parse_remote("ssh://git@github.com/owner/repo").unwrap();
        assert_eq!(r.host, "github.com");
        assert_eq!(r.owner, "owner");
        let r = parse_remote("git://github.com/owner/repo").unwrap();
        assert_eq!(r.host, "github.com");
        assert_eq!(r.owner, "owner");
    }

    #[test]
    fn parses_self_hosted_with_port() {
        let r = parse_remote("https://git.example.com:8080/owner/repo").unwrap();
        assert_eq!(r.kind, PlatformKind::SelfHosted);
        assert_eq!(r.host, "git.example.com");
        assert_eq!(r.port, Some(8080));
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        assert_eq!(r.origin(), "https://git.example.com:8080");
        assert_eq!(r.api_base("v4"), "https://git.example.com:8080/api/v4");
        assert_eq!(r.api_base("v1"), "https://git.example.com:8080/api/v1");
    }

    #[test]
    fn keeps_http_scheme_for_plain_http_remote() {
        let r = parse_remote("http://git.example.com/owner/repo").unwrap();
        assert_eq!(r.scheme, "http");
        assert_eq!(r.port, None);
        assert_eq!(r.api_base("v4"), "http://git.example.com/api/v4");
    }

    #[test]
    fn parses_https_with_userinfo() {
        let r = parse_remote("https://user@github.com/owner/repo").unwrap();
        assert_eq!(r.host, "github.com");
        assert_eq!(r.owner, "owner");
    }

    #[test]
    fn rejects_unsupported_scheme() {
        assert!(matches!(
            parse_remote("ftp://github.com/owner/repo"),
            Err(PlatformError::NotPlatform(_))
        ));
    }

    #[test]
    fn rejects_missing_repo() {
        assert!(matches!(
            parse_remote("https://github.com/owner"),
            Err(PlatformError::NotPlatform(_))
        ));
        assert!(matches!(
            parse_remote("https://github.com/"),
            Err(PlatformError::NotPlatform(_))
        ));
    }

    #[test]
    fn split_scp_like_rejects_urls_that_carry_userinfo() {
        // `https://user@host/…` is a scheme URL, not an scp-like remote: the
        // `/` in the user segment keeps it out of the scp arm.
        assert_eq!(
            strip_scheme("https://user@github.com/owner/repo"),
            Some(("https", "github.com", "owner/repo"))
        );
        assert_eq!(
            strip_scheme("ssh://git@github.com/owner/repo"),
            Some(("https", "github.com", "owner/repo"))
        );
        assert_eq!(
            strip_scheme("git@github.com:owner/repo"),
            Some(("https", "github.com", "owner/repo"))
        );
        // No `@`, or no `:` after it: not an scp-like form.
        assert_eq!(split_scp_like("github.com:owner/repo"), None);
        assert_eq!(split_scp_like("user@github.com"), None);
        // Empty user / empty host.
        assert_eq!(split_scp_like("@github.com:o/r"), None);
        assert_eq!(split_scp_like("user@:o/r"), None);
    }

    #[test]
    fn split_host_port_handles_ipv6_and_bad_ports() {
        assert_eq!(
            split_host_port("git.example.com"),
            ("git.example.com", None)
        );
        assert_eq!(
            split_host_port("git.example.com:8080"),
            ("git.example.com", Some(8080))
        );
        assert_eq!(split_host_port("[::1]"), ("[::1]", None));
        assert_eq!(split_host_port("[::1]:8080"), ("[::1]", Some(8080)));
        // Non-numeric port: classify the host anyway, drop the port.
        assert_eq!(split_host_port("host:not-a-port"), ("host", None));
    }

    #[test]
    fn parses_https_with_extra_path() {
        // v0.5.0 (`parses_https_with_extra_path`, deleted with no replacement):
        // everything after `repo` is noise, so the first two segments win.
        let r = parse_remote("https://github.com/owner/repo/issues/42").unwrap();
        assert_eq!(r.kind, PlatformKind::GitHub);
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        // The full path stays intact for platforms that need it (GitLab).
        assert_eq!(r.path, "owner/repo/issues/42");
    }

    #[test]
    fn parses_gitea_https_with_extra_path() {
        // Gitea's repository path is GitHub-shaped: `owner/repo` plus noise.
        let r = parse_remote("https://gitea.com/owner/repo/issues/42").unwrap();
        assert_eq!(r.kind, PlatformKind::Gitea);
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
    }

    #[test]
    fn gitlab_keeps_multi_level_namespace() {
        // Must not regress to the two-segment GitHub rule: the whole path is
        // GitLab's project id.
        let r = parse_remote("https://gitlab.com/group/sub/repo").unwrap();
        assert_eq!(r.kind, PlatformKind::GitLab);
        assert_eq!(r.owner, "group/sub");
        assert_eq!(r.repo, "repo");

        let r = parse_remote("https://gitlab.com/group/a/b/repo").unwrap();
        assert_eq!(r.owner, "group/a/b");
        assert_eq!(r.repo, "repo");
        assert_eq!(r.path, "group/a/b/repo");
    }

    #[test]
    fn self_hosted_uses_the_namespace_rule() {
        // Unknown family → GitLab semantics: a two-segment path is identical
        // either way, and a deeper path keeps its namespace.
        let r = parse_remote("https://git.example.com/owner/repo").unwrap();
        assert_eq!(r.owner, "owner");
        assert_eq!(r.repo, "repo");
        let r = parse_remote("https://git.example.com/group/sub/repo").unwrap();
        assert_eq!(r.owner, "group/sub");
        assert_eq!(r.repo, "repo");
    }

    #[test]
    fn missing_second_segment_keeps_v0_5_wording() {
        assert_eq!(
            parse_remote("https://github.com/owner"),
            Err(namespace_error("owner"))
        );
        assert_eq!(
            parse_remote("https://github.com/"),
            Err(namespace_error(""))
        );
        assert_eq!(
            parse_remote("https://github.com/owner/"),
            Err(namespace_error("owner"))
        );
    }

    #[test]
    fn split_namespace_requires_two_segments() {
        assert_eq!(
            split_namespace("owner/repo", PlatformKind::GitHub).unwrap(),
            ("owner".to_string(), "repo".to_string())
        );
        assert_eq!(
            split_namespace("owner/repo", PlatformKind::GitLab).unwrap(),
            ("owner".to_string(), "repo".to_string())
        );
        assert!(split_namespace("owner", PlatformKind::GitHub).is_err());
        assert!(split_namespace("", PlatformKind::GitHub).is_err());
        assert!(split_namespace("owner", PlatformKind::GitLab).is_err());
        assert!(split_namespace("", PlatformKind::GitLab).is_err());
    }

    #[test]
    fn split_namespace_reads_segments_per_platform() {
        // One path, two meanings: the last segment is GitLab's project, the
        // second segment is GitHub's repository.
        assert_eq!(
            split_namespace("group/sub/repo", PlatformKind::GitLab).unwrap(),
            ("group/sub".to_string(), "repo".to_string())
        );
        assert_eq!(
            split_namespace("group/sub/repo", PlatformKind::GitHub).unwrap(),
            ("group".to_string(), "sub".to_string())
        );
    }
}
